		/** 
		 * Tests creating a new Facility.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Facility");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Facility" );

			try {            
				Facility entity = FacilityService.getFacilityInstance().createFacility( generateNewEntity() );
				thePrimaryKey = entity.getFacilityId();
				LOGGER.info( "-- Successfully created a Facility with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Facility. 
		 */
		public Facility testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Facility" );

			Facility entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Facility with primary key" );
			msg.append( thePrimaryKey );
			
			FacilityFetchOneSummary fetchOneSummary = new FacilityFetchOneSummary( thePrimaryKey );

			try {
				entity = FacilityService.getFacilityInstance().getFacility( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Facility " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Facility.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Facility." );

			StringBuilder msg = new StringBuilder( "Failed to update a Facility : " );        
			Facility entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Facility." );

				// for use later on...
				thePrimaryKey = entity.getFacilityId();

				FacilityService proxy = FacilityService.getFacilityInstance();            
				proxy.updateFacility( entity );   

				LOGGER.info( "-- Successfully saved Facility - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Facility.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Facility." );

			try{
			    Facility entity = testRead(); 
				FacilityService.getFacilityInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Facility with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Facility with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Facilitys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Facilitys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Facility : " );        
			List<Facility> collection  = null;

			try {
				// call the static get method on the FacilityService
				collection = FacilityService.getFacilityInstance().getAllFacility();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Facility entity = null;            
					Iterator<Facility> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getFacilityId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

